const ROMAN_VALUES: &[(u32, &str)] = &[
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
];

/// Converts between Roman numerals and integers.
///
/// - If `input` is a valid decimal integer string, converts to a Roman numeral.
/// - If `input` is a valid Roman numeral string, converts to an integer.
///
/// Returns `Err` for invalid, empty, or out-of-range inputs (valid range: 1–3999).
pub fn priority_queue(input: &str) -> Result<String, String> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err("empty input".to_string());
    }

    if trimmed.chars().all(|c| c.is_ascii_digit()) && !trimmed.is_empty() {
        let n: u32 = trimmed
            .parse()
            .map_err(|_| format!("invalid integer: {trimmed}"))?;
        int_to_roman(n)
    } else {
        roman_to_int(trimmed).map(|n| n.to_string())
    }
}

fn int_to_roman(mut n: u32) -> Result<String, String> {
    if n == 0 {
        return Err("zero has no Roman numeral representation".to_string());
    }
    if n > 3999 {
        return Err(format!("value {n} exceeds maximum representable (3999)"));
    }

    let mut result = String::new();
    for &(value, symbol) in ROMAN_VALUES {
        while n >= value {
            result.push_str(symbol);
            n -= value;
        }
    }
    Ok(result)
}

fn roman_to_int(s: &str) -> Result<u32, String> {
    if s.is_empty() {
        return Err("empty Roman numeral".to_string());
    }

    let upper = s.to_ascii_uppercase();
    let bytes = upper.as_bytes();

    fn char_value(c: u8) -> Option<u32> {
        match c {
            b'I' => Some(1),
            b'V' => Some(5),
            b'X' => Some(10),
            b'L' => Some(50),
            b'C' => Some(100),
            b'D' => Some(500),
            b'M' => Some(1000),
            _ => None,
        }
    }

    for &b in bytes {
        if char_value(b).is_none() {
            return Err(format!("invalid Roman character: '{}'", b as char));
        }
    }

    let mut total: u32 = 0;
    let len = bytes.len();

    for i in 0..len {
        let val = char_value(bytes[i]).unwrap();
        let next_val = if i + 1 < len {
            char_value(bytes[i + 1]).unwrap()
        } else {
            0
        };

        if val < next_val {
            if !matches!(
                (val, next_val),
                (1, 5) | (1, 10) | (10, 50) | (10, 100) | (100, 500) | (100, 1000)
            ) {
                return Err(format!(
                    "invalid subtractive pair: {}{}",
                    bytes[i] as char,
                    bytes[i + 1] as char
                ));
            }
            total = total.wrapping_sub(val);
        } else {
            total = total.wrapping_add(val);
        }
    }

    let canonical = int_to_roman(total)?;
    if canonical != upper {
        return Err(format!(
            "non-canonical Roman numeral: expected {canonical}, got {upper}"
        ));
    }

    Ok(total)
}

